# Clarified spec:
# Return the percentage change from an old value to a new value, rounded to one decimal place. When the old value is negative, the percentage change is computed using that negative value (not its absolute value). The result is rounded to one decimal place using Python's round() which applies banker's rounding (round-half-to-even). For example, percentage_change(-10.0, 10.0) returns -200.
import datetime as _dt
import decimal as _decimal
import fractions as _fractions
import json
import math as _math

import pytest

from solution import percentage_change  # noqa: E402  (put your implementation in solution.py)

