@pytest.mark.parametrize("args_json,expected", CASES)
def test_percentage_change(args_json, expected):
    args = json.loads(args_json)
    if expected == RAISES:
        with pytest.raises(Exception):
            percentage_change(**args)
    else:
        assert canon(percentage_change(**args)) == expected

